import numpy as np
lam1 = 1.1071
eps, A, B = 11.6858, 0.939816, 8.10461e-3

def n_code(wl):
    wl2 = wl**2
    return np.sqrt(eps + A/wl2 + B*wl2/(wl2 - lam1**2))

def n_ref(wl):
    wl2 = wl**2
    return np.sqrt(eps + A/wl2 + B*lam1**2/(wl2 - lam1**2))

def n_ch(wl):  # Chandler-Horowitz & Amirtharaj 2005, 2.5-22 um
    wl2 = wl**2
    return np.sqrt(11.67316 + 1.0/wl2 + 0.004482633/(wl2 - 1.108205**2))

pts = []
seen = set()
for line in open('/tmp/li293.yml'):
    parts = line.split()
    if len(parts) == 2:
        try:
            wl, n = float(parts[0]), float(parts[1])
        except ValueError:
            continue
        if wl in seen: continue
        seen.add(wl)
        pts.append((wl, n))

print(' wl     Li-tab    code      ref       CH2005')
for wl, n in pts:
    if wl in (1.2, 1.55, 2.0, 3.0, 5.0, 8.0, 10.0, 14.0):
        ch = n_ch(wl) if wl >= 2.5 else float('nan')
        print(f'{wl:5.2f}  {n:.4f}   {n_code(wl):.4f}   {n_ref(wl):.4f}   {ch:.4f}')
